SELECT approval_id AS approvalId,approval_no AS approvalNo,approval_type AS approvalType,business_domain AS businessDomain,title,requester_employee_no AS requesterEmployeeNo,approval_status AS approvalStatus,current_step_no AS currentStepNo,version_no AS versionNo,created_at AS createdAt,updated_at AS updatedAt FROM bza_approval_document WHERE (:status IS NULL OR approval_status=:status) AND (:employeeNo IS NULL OR requester_employee_no=:employeeNo) ORDER BY approval_id DESC LIMIT :limit
